sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    if (isLoading || newValue === '') {
        return;
    }

    // Prevents invalid typing formats (based on local format)
    var selectedDateMs = getDateFromFormat(newValue, g_user_date_format);
	if (selectedDateMs === 0) {
        g_form.clearValue('date');
        g_form.showFieldMsg('date', 'Error: Invalid date format. Please use the calendar icon to select a date.', 'error');
        return; 
    }

    // If the selected date is strictly before tomorrow (STRY 11)
    var today = new Date();
    var tomorrow = new Date(today.getFullYear(), today.getMonth(), today.getDate() + 1);

    if (selectedDateMs < tomorrow.getTime()) {
        g_form.clearValue('date');
        g_form.showFieldMsg('date', 'Error: You can only schedule training sessions for tomorrow or later.', 'error');
        return;
    }

    // Prevents duplicate schedules for the same course (STRY 3)
    var courseId = g_form.getValue('course');

    // Halt execution if the course field is not yet populated
    if (!courseId) {
		g_form.showFieldMsg('date', 'Error: Choose a course first!', 'error');
		g_form.clearValue('date');
        return;
    }

    // Calls the Script Include via GlideAjax to check the database for existing schedules
    var ga = new GlideAjax('x_1960572_training.TrainingHubUtils');
    ga.addParam('sysparm_name', 'checkDuplicateDate');
    ga.addParam('sysparm_course', courseId);
    ga.addParam('sysparm_date', newValue);
    ga.addParam('sysparm_id', g_form.getUniqueValue()); 

    ga.getXMLAnswer(function(answer) {
        if (answer === 'true') {
            // Clears the date field and display an error message if a conflict is found
            g_form.clearValue('date'); 
            g_form.showFieldMsg('date', 'Error: A training session for this course is already scheduled on this date!', 'error');
        }
    });
}
